def solve_small(N, s):
    # Positions for the s x s tiles are (r, c) where 1 <= r, c <= N-s+1
    # Let P = N-s+1
    # A is a P x P matrix of counts
    # x_ij = sum_{r,c in Window(i,j)} A_rc
    # For each (i,j), Window(i,j) = [i-s+1, i] x [j-s+1, j] intersected with [1, P] x [1, P]

    P = N - s + 1
    max_k = 0

    # Since we want to maximize the frequency of a non-zero value,
    # we can try small values for A_rc.
    # But there are many A_rc. Let's try a simpler approach.
    # A_rc can only be small because we're looking for a small non-zero value c.
    # Let's try A_rc in {0, 1, 2}.
    import itertools
    for A_flat in itertools.product([0, 1, 2], repeat=P*P):
        A = [list(A_flat[i*P : (i+1)*P]) for i in range(P)]
        x = [[0]*N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                count = 0
                for r in range(max(1, i-s+2), min(i+1, P+1)):
                    for c in range(max(1, j-s+2), min(j+1, P+1)):
                        count += A[r-1][c-1]
                x[i][j] = count

        # Count frequencies of non-zero values
        counts = {}
        for i in range(N):
            for j in range(N):
                val = x[i][j]
                if val > 0:
                    counts[val] = counts.get(val, 0) + 1

        if counts:
            max_k = max(max_k, max(counts.values()))

    return max_k

