    N = 2011
    M = 52

    def get_counts(R, M, N):
        counts = {}
        for i in range(1, N + 1):
            ni = max(0, min(i, R) - max(1, i-M+1) + 1)
            if ni > 0:
                counts[ni] = counts.get(ni, 0) + 1
        return counts

    # The counts of n_i depend only on R.
    # Let's see how many distinct count dictionaries we can have.
    # R can be from 1 to N+M.
    # But R > N will give the same n_i for a fixed N.
    # Let's check R from 1 to N+M.

    all_counts = []
    for R in range(1, N + M + 1):
        c = get_counts(R, M, N)
        if c not in all_counts:
            all_counts.append(c)

    print(f"Number of distinct count dictionaries: {len(all_counts)}")

    # Now we want to find max_R, max_C, max_v:
    # k = sum_{d | v} count_n(d) * count_m(v/d)

    # Wait, we can just iterate over all R and C.
    # But we can also iterate over all pairs of dictionaries.

    max_k = 0
    for count_n in all_counts:
        for count_m in all_counts:
            # For each pair of dictionaries, find the best v.
            # v can be anything from 1 to max(n_i) * max(m_j).
            # max(n_i) is min(R, M) and max(m_j) is min(C, M).
            # So v can be up to M*M = 52*52 = 2704.

            # Let's pre-calculate the max_v for this pair.
            # v can be anything that can be formed as d * (v/d)
            # where d is a key in count_n and v/d is a key in count_m.

            # To optimize, we can iterate over d in count_n and v_m in count_m.
            # Then v = d * v_m.
            # But we need to be careful, because multiple (d, v_m) can give the same v.
            # For a fixed v, k_v = sum_{d|v} count_n(d) * count_m(v/d).

            # Let's find all possible v's.
            possible_vs = {}
            for d, c_n in count_n.items():
                for v_m, c_m in count_m.items():
                    v = d * v_m
                    if v > 0:
                        if v not in possible_vs:
                            possible_vs[v] = 0
                        # This is not correct, we need to sum for each v.
                        pass

            # Let's do it correctly:
            v_sums = {}
            for d, c_n in count_n.items():
                for v_m, c_m in count_m.items():
                    v = d * v_m
                    v_sums[v] = v_sums.get(v, 0) + c_n * c_m

            if v_sums:
                max_k = max(max_k, max(v_sums.values()))

    return max_k

